package methodsandconstructor;

public class FunctionWithNoReturnAndNoParameter {
	public void AreaOfRectangle() {
	float l=2.2f,b=2.3f,area;
	area=l*b;
	System.out.println("area= "+area);
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		FunctionWithNoReturnAndNoParameter ob=new FunctionWithNoReturnAndNoParameter();
		ob.AreaOfRectangle();
		

	}

}
